from pathlib import Path
import json,subprocess,sys
from afterlife.compiler import _canonical,_hash
root=Path(sys.argv[1]);specfile=root/'spec.json';current=root/'current.json';csv=root/'patch.csv';out=root/'patched.json';review=root/'review.json';spec=json.loads((Path(__file__).resolve().parents[1]/'examples/task-tracker/app.json').read_text());records=[{'id':'row-'+str(i),'title':'Job '+str(i),'status':'Planned','notes':'PRIVATE retained\r\n猫 '+str(i),'hours':i,'important':False}for i in range(205)]
