if len(sys.argv)==2:
 specfile.write_text(json.dumps(spec));current.write_text(json.dumps({'format':'afterlife-data/v1','app_id':spec['app_id'],'spec_fingerprint':_hash(_canonical(spec)),'records':records}));old=current.read_bytes();text='id,title,hours\r\nrow-0,=literal formula,-1\r\nrow-103,"PRIVATE exact 猫, quote ""x""",\r\nrow-204,Last exact,9007199254740991\r\n';csv.write_text(text,newline='');base=['patch-csv',specfile,current,csv,'--text-policy','literal','-o',out,'--review',review];r=cli(*base);assert r.returncode==0,r.stderr;expected=[{**row,**({'title':'=literal formula','hours':-1}if i==0 else{'title':'PRIVATE exact 猫, quote "x"','hours':None}if i==103 else{'title':'Last exact','hours':9007199254740991}if i==204 else{})}for i,row in enumerate(records)];assert json.loads(out.read_text())['records']==expected;assert 'PRIVATE'not in r.stdout and'PRIVATE'not in review.read_text();assert json.loads(review.read_text())['counts']['changed']==3;before=out.read_bytes();before_review=review.read_bytes()
 for bad in [text+'unknown,New,1\r\n',text+'row-0,Duplicate,1\r\n',text.replace('9007199254740991','9007199254740992'),text.replace('id,title,hours','id,title,unknown'),text+'row-1,broken\r\n']:
  csv.write_text(bad,newline='');r=cli(*base,'--force');assert r.returncode==2 and not r.stdout;assert out.read_bytes()==before and review.read_bytes()==before_review and current.read_bytes()==old
 csv.write_text(text,newline='');r=cli('from-export',specfile,out,'--review',review,'--against',current,'-o',root/'app.html');assert r.returncode==0,r.stderr;assert current.read_bytes()==old;(root/'expected.json').write_text(json.dumps(expected))
else:assert json.loads((root/'browser.json').read_text())['records']==json.loads((root/'expected.json').read_text())
